require "rails_helper"

RSpec.describe Timekeeping::ReservationDerivation do
  it "refuses a recorded invoice number that is not one of the named company's invoices and reserves nothing" do
    entry_row = { "id" => 5, "company_id" => 1, "locked" => false, "version" => 0 }
    # "INV-9" belongs to another company, so it is absent from this company's invoice numbers.
    result = described_class.derive(
      company_id: 1,
      entries: [{ id: 5, locked: false, company_id: 1, join_company_id: 1, row: entry_row }],
      links: [{ entry_id: 5, invoice_id: 10, invoice_company_id: 1, draft: false, discarded: false }],
      invoice_numbers: { 10 => "INV-1" },
      recorded_invoices: { "INV-9" => { "entry_ids" => [5], "disposition" => "reserve" } },
      generation: 7,
      captured_at: Time.utc(2026, 10, 25, 12)
    )

    # "Refuse, never guess, when a number is missing, matches no invoice of that company, or would link an entry to another company's invoice."
    expect(result[:reservations]).to be_empty
    expect(result[:corrections]).to be_empty
    expect(result[:refusals]).not_to be_empty
    expect(result[:refusals].join("\n")).to include("INV-9")
  end
end

