RSpec.describe Timekeeping::ReservationDerivation do
  it "gives the same entry and invoice ids different operation ids in different companies" do
    captured_at = Time.utc(2026, 10, 25, 12)
    derive_for = lambda do |company_id|
      entry_row = { "id" => 5, "company_id" => company_id, "locked" => true, "version" => 0 }
      described_class.derive(
        company_id:,
        entries: [{ id: 5, locked: true, company_id:, join_company_id: company_id, row: entry_row }],
        links: [{ entry_id: 5, invoice_id: 10, invoice_company_id: company_id, draft: false, discarded: false }],
        invoice_numbers: { 10 => "INV-1" },
        recorded_invoices: {},
        generation: 7,
        captured_at:
      )
    end

    first = derive_for.call(1)[:reservations].sole
    second = derive_for.call(2)[:reservations].sole

    # "a reservation's `operation_id` is a UUIDv5 of company, entry and invoice"
    expect(first["company_id"]).to eq(1)
    expect(second["company_id"]).to eq(2)
    expect(first["operation_id"]).not_to eq(second["operation_id"])
  end
end

RSpec.describe Timekeeping::ReservationDerivation do
  let(:captured_at_for_recorded_checks) { Time.utc(2026, 10, 25, 12) }

  def derive_unlocked_link_for_recorded_checks(invoice_numbers:, recorded_invoices:)
    described_class.derive(
      company_id: 1,
      entries: [
        { id: 5, locked: false, company_id: 1, join_company_id: 1, row: { "id" => 5, "company_id" => 1, "locked" => false, "version" => 0 } },
        { id: 6, locked: false, company_id: 1, join_company_id: 1, row: { "id" => 6, "company_id" => 1, "locked" => false, "version" => 0 } }
      ],
      links: [{ entry_id: 5, invoice_id: 10, invoice_company_id: 1, draft: false, discarded: false }],
      invoice_numbers:,
      recorded_invoices:,
      generation: 7,
      captured_at: captured_at_for_recorded_checks
    )
  end

  it "refuses a recorded disposition other than reserve" do
    result = derive_unlocked_link_for_recorded_checks(
      invoice_numbers: { 10 => "INV-1" },
      recorded_invoices: { "INV-1" => { "entry_ids" => [5], "disposition" => "release" } }
    )

    expect(result[:refusals].join("\n")).to include("INV-1", "release")
    expect(result[:reservations]).to be_empty
    expect(result[:corrections]).to be_empty
  end

  it "refuses a recorded entry that is not a live unlocked link of that invoice" do
    result = derive_unlocked_link_for_recorded_checks(
      invoice_numbers: { 10 => "INV-1" },
      recorded_invoices: { "INV-1" => { "entry_ids" => [5, 6], "disposition" => "reserve" } }
    )

    expect(result[:refusals].join("\n")).to include("INV-1")
    expect(result[:reservations]).to be_empty
  end

  it "refuses an unlocked link whose invoice has no number" do
    result = derive_unlocked_link_for_recorded_checks(invoice_numbers: { 10 => nil }, recorded_invoices: {})

    expect(result[:refusals].join("\n")).to include("entry 5", "invoice 10")
    expect(result[:reservations]).to be_empty
  end

  it "derives operation_id as the RFC 4122 UUIDv5 of company, entry and invoice under the fixed namespace" do
    expect(described_class.operation_id(company_id: 1, entry_id: 2, invoice_id: 3))
      .to eq("d144e460-1f35-5745-b31c-a17874ecd9b3")
  end
end
